"""Labeling module using Triple Barrier method.

Generates a labelled dataset from the engineered features and saves it as CSV.
"""
import os
import pandas as pd

from trading_engine.ml.dataset import TripleBarrierLabeler

def label_data():
    """Create labelled dataset and persist to CSV.

    Returns:
        pd.DataFrame: Dataframe with labeling columns.
    """
    # Load engineered features (Parquet) generated by feature_engine.py
    features_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "data", "VN30F1M_features.parquet"))
    if not os.path.exists(features_path):
        raise FileNotFoundError(f"Features file not found at {features_path}. Run the feature engineering step first.")
    df = pd.read_parquet(features_path)

    labeler = TripleBarrierLabeler()
    labeled_df = labeler.create_dataset(df)

    # Save labelled dataset for training/prediction
    output_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "data", "ml_dataset.csv"))
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    labeled_df.to_csv(output_path, index=False)
    print(f"Labelled dataset saved to {output_path}")
    return labeled_df
